/**
 * Parity check: the TypeScript engine must reproduce the Python benchmark exactly.
 * Compares model, tier, tool sequence and cost for 30 tasks x 3 policies against
 * scripts/fixtures/benchmark_report.json (generated by `python -m evals.benchmark`).
 */
import { readFileSync } from 'node:fs';
import { Agent, Gateway, MOCK_MODELS, Registry, defaultIndex } from '../lib/engine.js';

interface Task { id: string; mode: 'agent' | 'chat'; prompt: string; chaos: string | null }
interface Row { id: string; model: string; tier: string; cost_usd: number; tools: string[] }

const tasks = JSON.parse(readFileSync(new URL('./fixtures/tasks.json', import.meta.url), 'utf8')) as Task[];
const report = JSON.parse(readFileSync(new URL('./fixtures/benchmark_report.json', import.meta.url), 'utf8')) as {
  results: Record<string, { rows: Row[] }>;
};

let checked = 0;
const bad: string[] = [];
for (const policy of ['always-cheap', 'always-strong', 'smart-router']) {
  const expected = new Map(report.results[policy].rows.map((r) => [r.id, r]));
  for (const t of tasks) {
    const gw = new Gateway(new Registry(MOCK_MODELS), { cacheEnabled: false, sleep: async () => undefined, rng: () => 0.5 });
    const agent = new Agent(gw, defaultIndex());
    const got = t.mode === 'agent' ? await agent.run(t.prompt, policy, t.chaos) : await gw.chat(t.prompt, policy, t.chaos);
    const want = expected.get(t.id) as Row;
    const tools = got.tools_used ?? [];
    const same =
      got.model === want.model &&
      got.tier === want.tier &&
      Math.abs(got.cost_usd - want.cost_usd) < 1e-12 &&
      JSON.stringify(tools) === JSON.stringify(want.tools);
    checked++;
    if (!same) bad.push(`${policy}/${t.id}: got ${got.model}/${got.tier}/${got.cost_usd}/${tools} want ${want.model}/${want.tier}/${want.cost_usd}/${want.tools}`);
  }
}
if (bad.length) {
  console.error(`PARITY FAILED (${bad.length}/${checked})\n` + bad.join('\n'));
  process.exit(1);
}
console.log(`parity OK: ${checked} task runs match the Python reference (model, tier, tools, cost)`);
